with with_prev as (select *, lag(started_at) over (partition by device order by started_at, id) as prev_started_at from sessions), with_gaps as (select *, case when prev_started_at is null or started_at > prev_started_at + interval '60' day then 1 else 0 end as is_new_burst from with_prev), sessionized as (select id, customer_id, device, browser, started_at, country, sum(is_new_burst) over (partition by device order by started_at, id rows between unbounded preceding and current row) as session_id from with_gaps) select device, date_trunc('month', started_at) as activity_month, round(sum(session_id) / nullif(count(case when country = 'TH' then 1 end), 0), 2) as session_id_per_th, round(sum(session_id) / nullif(count(case when device = 'desktop' then 1 end), 0), 2) as session_id_per_desktop, min(started_at) as started_at, count(*) as cnt, min(session_id) as min_session_id from sessionized group by 1, 2 order by activity_month desc
